                  <div className="actions-row" style={{ marginTop: 0, marginBottom: 'var(--sp-3)' }}>
                    <button className="mini" data-thanks-group onClick={() => openDraft('The thank-you', draftThankYou(event, profile))}>One note for everyone</button>
                  </div>
